WITH base_bal AS (     SELECT CTACTB,            SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE)) THEN VLRLANC ELSE 0 END) AS mov_atu,            SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) THEN VLRLANC ELSE 0 END) AS mov_ant,            SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 2 YEAR)) THEN VLRLANC ELSE 0 END) AS mov_ant2,            SUM(CASE WHEN YEAR(REFERENCIA) <= YEAR(DATE(:VAR_DATA_REF_DRE)) THEN VLRLANC ELSE 0 END) AS acum_atu,            SUM(CASE WHEN YEAR(REFERENCIA) <= YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) THEN VLRLANC ELSE 0 END) AS acum_ant,            SUM(CASE WHEN YEAR(REFERENCIA) <= YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 2 YEAR)) THEN VLRLANC ELSE 0 END) AS acum_ant2     FROM IMP_BASE_BALANCETE     WHERE CODEMP = :VAR_EMPRESA_DRE       AND YEAR(REFERENCIA) <= YEAR(DATE(:VAR_DATA_REF_DRE))     GROUP BY CTACTB ), base_exclusao AS (     SELECT DET.ORDEM,            SUM(CASE WHEN YEAR(B.REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE)) THEN ABS(IFNULL(B.VLRLANC, 0)) * DETCTACTB_EXC.SINAL ELSE 0 END) AS valor_exclusao_atual,            SUM(CASE WHEN YEAR(B.REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) THEN ABS(IFNULL(B.VLRLANC, 0)) * DETCTACTB_EXC.SINAL ELSE 0 END) AS valor_exclusao_anterior     FROM ESTR_DEMONSTRATIVOS EST     INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO     INNER JOIN DET_DEMONSTRATIVO_REFERENCIA DETREF ON DET.ID = DETREF.ID_DET_DEMONSTRATIVO AND DETREF.REFERENCIA = DATE(:VAR_DATA_REF_DRE)     INNER JOIN DET_DEMONSTRATIVO_CTACTB_EXC DETCTACTB_EXC ON DETREF.ID = DETCTACTB_EXC.ID_DET_DEMONSTRATIVO_REFERENCIA     LEFT JOIN IMP_BASE_BALANCETE B ON B.CTACTB = DETCTACTB_EXC.PADRAO_CTACTB AND B.CODEMP = :VAR_EMPRESA_DRE          AND (YEAR(B.REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE)) OR YEAR(B.REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)))     WHERE EST.ID IN (10)     GROUP BY DET.ORDEM ), outros_dfc_191 AS (     SELECT SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE(:VAR_DATA_REF_DRE)) THEN VLRLANC ELSE 0 END) AS valor_atual,            SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 1 YEAR)) THEN VLRLANC ELSE 0 END) AS valor_anterior,            SUM(CASE WHEN YEAR(REFERENCIA) = YEAR(DATE_SUB(DATE(:VAR_DATA_REF_DRE), INTERVAL 2 YEAR)) THEN VLRLANC ELSE 0 END) AS valor_anterior2     FROM OUTROS_DFC     WHERE CODEMP = :VAR_EMPRESA_DRE ), base_valores AS (     SELECT DET.ORDEM, DET.NOME_GRUPO AS DESCRICAO, DET.VARIACAO,            SUM(IFNULL(BB.mov_atu, 0) * DETCTACTB.SINAL) AS base_atual,            SUM(IFNULL(BB.mov_ant, 0) * DETCTACTB.SINAL) AS base_anterior,            SUM(IFNULL(BB.mov_ant2, 0) * DETCTACTB.SINAL) AS base_anterior2,            SUM(IFNULL(BB.acum_atu, 0) * DETCTACTB.SINAL) AS acum_atual,            SUM(IFNULL(BB.acum_ant, 0) * DETCTACTB.SINAL) AS acum_anterior,            SUM(IFNULL(BB.acum_ant2, 0) * DETCTACTB.SINAL) AS acum_anterior2     FROM ESTR_DEMONSTRATIVOS EST     INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO     INNER JOIN DET_DEMONSTRATIVO_REFERENCIA DETREF ON DET.ID = DETREF.ID_DET_DEMONSTRATIVO AND DETREF.REFERENCIA = DATE(:VAR_DATA_REF_DRE)     LEFT JOIN DET_DEMONSTRATIVO_CTACTB DETCTACTB ON DETREF.ID = DETCTACTB.ID_DET_DEMONSTRATIVO_REFERENCIA     LEFT JOIN base_bal BB ON BB.CTACTB = DETCTACTB.PADRAO_CTACTB     WHERE EST.ID IN (10)     GROUP BY DET.ORDEM, DET.NOME_GRUPO, DET.VARIACAO ) SELECT BV.ORDEM,        BV.DESCRICAO,        BV.VARIACAO,        CASE WHEN BV.ORDEM = '1.9.1' AND BV.base_atual = 0 THEN (SELECT valor_atual FROM outros_dfc_191) ELSE BV.base_atual END / 1000 AS valor_base_atual,        CASE WHEN BV.ORDEM = '1.9.1' AND BV.base_anterior = 0 THEN (SELECT valor_anterior FROM outros_dfc_191) ELSE BV.base_anterior END / 1000 AS valor_base_anterior,        CASE WHEN BV.ORDEM = '1.9.1' THEN (SELECT valor_anterior2 FROM outros_dfc_191) ELSE BV.base_anterior2 END / 1000 AS valor_base_anterior2,        (CASE WHEN BV.ORDEM = '5.1' THEN BV.acum_anterior              WHEN BV.ORDEM = '5.2' THEN BV.acum_atual              WHEN BV.VARIACAO = 'Sim' THEN BV.acum_anterior - BV.acum_atual              WHEN BV.ORDEM = '1.9.1' AND BV.base_atual = 0 THEN (SELECT valor_atual FROM outros_dfc_191)              ELSE BV.base_atual END - IFNULL(BEX.valor_exclusao_atual, 0)) / 1000 AS VALOR_ANO_ATUAL,        (CASE WHEN BV.ORDEM = '5.1' THEN BV.acum_anterior2              WHEN BV.ORDEM = '5.2' THEN BV.acum_anterior              WHEN BV.VARIACAO = 'Sim' THEN BV.acum_anterior2 - BV.acum_anterior              WHEN BV.ORDEM = '1.9.1' AND BV.base_anterior = 0 THEN (SELECT valor_anterior FROM outros_dfc_191)              ELSE BV.base_anterior END - IFNULL(BEX.valor_exclusao_anterior, 0)) / 1000 AS VALOR_ANO_ANTERIOR FROM base_valores BV LEFT JOIN base_exclusao BEX ON BEX.ORDEM = BV.ORDEM ORDER BY BV.ORDEM